import { Hono } from "hono";
import { one } from "../one/index.js";

// Acme standup bot: posts the day's standup to Slack and files it in Notion.
const SLACK_POST = { platform: "slack", actionId: "conn_mod_def::GJ7H84zBlaI::BCfuA16aTaGVIax5magsLA", method: "POST", path: "/chat.postMessage", access: "write" } as const;
const SLACK_CHANNELS = { platform: "slack", actionId: "conn_mod_def::GJ7H9zmRFIk::1RxrzeicS-ibnXF4sFC5Ww", method: "GET", path: "/conversations.list", access: "read" } as const;
const NOTION_PAGES = { platform: "notion", actionId: "conn_mod_def::GHmt2usus_k::6Dk4f-RQSqq6WmD5WOkdJQ", method: "POST", path: "/v1/notion/create-multiple-pages", access: "write" } as const;

export const standup = new Hono();
standup.get("/api/channels", async (c) => c.json(await one.call(c, { action: SLACK_CHANNELS, sample: () => ({ channels: [] }) })));
standup.post("/api/standup", async (c) => {
  const { channel, text } = await c.req.json();
  await one.call(c, { action: SLACK_POST, body: { channel, text }, sample: () => ({ ok: true }) });
  await one.call(c, { action: NOTION_PAGES, body: { pages: [{ title: "Standup", content: text }] }, sample: () => ({}) });
  return c.json({ ok: true });
});

import { Hono } from "hono";
import Stripe from "stripe";
import { one } from "../one/index.js";

const LIST_CUSTOMERS = { platform: "stripe", actionId: "conn_mod_def::GJ7KsRfyH8M::DEPSKKu2TUK22IjVPP1Hfg", method: "GET", path: "/customers", access: "read" } as const;

export const customers = new Hono();
customers.get("/api/customers", async (c) => c.json(await one.call(c, { action: LIST_CUSTOMERS, query: { limit: "20" }, sample: () => ({ data: [] }) })));

// Left over from before One: a direct Stripe client with a secret key.
const stripe = new Stripe(process.env.STRIPE_SECRET_KEY ?? "");
customers.get("/api/customers/raw", async (c) => c.json(await stripe.customers.list({ limit: 5 })));
